export class ExprError extends Error {
  /**
   * @param {string} message reason, ending with the position it refers to
   * @param {number} index 0-based index into the source, in UTF-16 code units
   */
  constructor(message, index) {
    super(message);
    this.name = 'ExprError';
    this.index = index;
  }
}

const WHITESPACE = /\s/;
const NAME_START = /[A-Za-z_]/;
const NAME_PART = /[A-Za-z0-9_]/;
const NUMBER = /(?:\d+(?:\.\d+)?|\.\d+)(?:[eE][+-]?\d+)?/y;
const PUNCTUATION = { '(': 'lparen', ')': 'rparen', ',': 'comma' };
const OPERATORS = new Set(['+', '-', '*', '/', '%', '^']);

/**
 * Split an expression into tokens, keeping the raw source text of each one.
 *
 * @param {string} input expression source
 * @returns {{ tokens: object[], texts: string[] }} tokens and their source slices
 */
export function tokenizeWithText(input) {
  const source = String(input);
  const tokens = [];
  const texts = [];
  let position = 0;

  while (position < source.length) {
    const character = source[position];

    if (WHITESPACE.test(character)) {
      position += 1;
      continue;
    }

    if (character >= '0' && character <= '9') {
      position = readNumber(source, position, tokens, texts);
      continue;
    }

    if (character === '.' && /\d/.test(source[position + 1] ?? '')) {
      position = readNumber(source, position, tokens, texts);
      continue;
    }

    if (NAME_START.test(character)) {
      const start = position;
      position += 1;
      while (position < source.length && NAME_PART.test(source[position])) position += 1;
      const text = source.slice(start, position);
      tokens.push({ type: 'name', value: text, index: start });
      texts.push(text);
      continue;
    }

    if (OPERATORS.has(character)) {
      tokens.push({ type: 'operator', value: character, index: position });
      texts.push(character);
      position += 1;
      continue;
    }

    const punctuation = PUNCTUATION[character];
    if (punctuation !== undefined) {
      tokens.push({ type: punctuation, value: character, index: position });
      texts.push(character);
      position += 1;
      continue;
    }

    const codePoint = String.fromCodePoint(source.codePointAt(position));
    throw new ExprError(`unexpected character '${codePoint}' at ${position}`, position);
  }

  return { tokens, texts };
}

/** Read one numeric literal, rejecting anything that only starts like a number. */
function readNumber(source, start, tokens, texts) {
  NUMBER.lastIndex = start;
  const match = NUMBER.exec(source);
  if (match === null || match.index !== start) throw new ExprError(`malformed number at ${start}`, start);
  const end = start + match[0].length;
  const next = source[end];
  if (next !== undefined && (next === '.' || NAME_PART.test(next))) {
    throw new ExprError(`malformed number at ${start}`, start);
  }
  tokens.push({ type: 'number', value: Number(match[0]), index: start });
  texts.push(match[0]);
  return end;
}

/**
 * Split an expression into tokens.
 *
 * @param {string} input expression source
 * @returns {{ type: 'number' | 'name' | 'operator' | 'lparen' | 'rparen' | 'comma', value: number | string, index: number }[]}
 *   tokens in source order
 */
export function tokenize(input) {
  return tokenizeWithText(input).tokens;
}
