  let left = parseUnary(state);
  while (isOperator(peek(state), MULTIPLICATIVE)) {
    const token = state.tokens[state.position];
    state.position += 1;
    const right = parseUnary(state);
    left = { type: 'binary', op: token.value, left, right, index: token.index };
  }
  return left;
