  sqrt: { min: 1, max: 1, apply: (a) => Math.sqrt(a) },
  floor: { min: 1, max: 1, apply: (a) => Math.floor(a) },
  ceil: { min: 1, max: 1, apply: (a) => Math.ceil(a) },
  round: { min: 1, max: 1, apply: (a) => Math.round(a) },
  sign: { min: 1, max: 1, apply: (a) => Math.sign(a) },
  pow: { min: 2, max: 2, apply: (a, b) => a ** b },
  atan2: { min: 2, max: 2, apply: (a, b) => Math.atan2(a, b) },
  min: { min: 1, max: Infinity, apply: (...values) => Math.min(...values) },
  max: { min: 1, max: Infinity, apply: (...values) => Math.max(...values) },
